<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();if(!in_array($_SESSION['role'],['system_admin','sub_admin'],true)){http_response_code(403);exit('Audit logs are available to System Admins and Sub System Admins.');}
$page=max(1,(int)($_GET['page']??1));$perPage=40;$action=trim((string)($_GET['action']??''));$entity=trim((string)($_GET['entity']??''));$actor=trim((string)($_GET['actor']??''));$where=[];$params=[];if($action!==''){$where[]='l.action=?';$params[]=$action;}if($entity!==''){$where[]='l.entity_type=?';$params[]=$entity;}if($actor!==''){$where[]='(u.name LIKE ? OR u.email LIKE ? OR u.username LIKE ?)';array_push($params,"%$actor%","%$actor%","%$actor%");}$clause=$where?'WHERE '.implode(' AND ',$where):'';$db=db();$count=$db->prepare("SELECT COUNT(*) FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_id $clause");$count->execute($params);$total=(int)$count->fetchColumn();$offset=($page-1)*$perPage;$q=$db->prepare("SELECT l.id,l.action,l.entity_type,l.entity_id,l.details,l.created_at,u.name actor_name,u.email,u.username FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_id $clause ORDER BY l.created_at DESC LIMIT $perPage OFFSET $offset");$q->execute($params);$logs=$q->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit log · ShuleLite</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">SYSTEM</div><nav class="side-nav" aria-label="System navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="team.php">♧ &nbsp;Team</a><a class="nav-item active" href="audit.php" aria-current="page">◷ &nbsp;Audit log</a></nav><div class="sidebar-bottom"><a class="nav-item" href="profile.php">◉ &nbsp;My account</a><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">System <span>/</span> Audit log</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$_SESSION['role']))?></span><div class="user-name"><?=e($_SESSION['name'])?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">ACCOUNTABILITY</div><h1>Audit log</h1><p class="muted">Review recorded account, school and data changes.</p></div></section><form method="get" class="note-create"><div class="form-grid"><div><label for="actor">Changed by</label><input id="actor" name="actor" value="<?=e($actor)?>" placeholder="Name, email or username"></div><div><label for="action">Action</label><select id="action" name="action"><option value="">All actions</option><?php foreach(['create','assign_role','reset_password','suspend','reactivate','activate_role','deactivate_role'] as $option):?><option value="<?=$option?>" <?=$action===$option?'selected':''?>><?=e(ucfirst(str_replace('_',' ',$option)))?></option><?php endforeach;?></select></div><div><label for="entity">Record type</label><select id="entity" name="entity"><option value="">All record types</option><?php foreach(['user','school','pupil','pupil_result','teacher_assignment','learning_note'] as $option):?><option value="<?=$option?>" <?=$entity===$option?'selected':''?>><?=e(ucfirst(str_replace('_',' ',$option)))?></option><?php endforeach;?></select></div></div><button class="button primary" type="submit">Filter log</button></form><section class="content-section"><div class="section-heading"><div><div class="eyebrow">RECENT ACTIVITY</div><h2><?=number_format($total)?> recorded events</h2></div></div><?php if(!$logs):?><div class="empty-state"><h3>No matching events</h3><p>Try clearing a filter or check back after changes are recorded.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Date and time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(date('j M Y H:i',strtotime($log['created_at'])))?></td><td><?=e($log['actor_name']?:'Deleted account')?></td><td><?=e(ucfirst(str_replace('_',' ',$log['action'])))?></td><td><?=e(str_replace('_',' ',$log['entity_type']))?> #<?=e((string)($log['entity_id']??'—'))?></td><td><?=e($log['details']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if($total>$perPage):?><nav class="pagination" aria-label="Audit log pages"><?php if($page>1):?><a class="button" href="?<?=http_build_query(array_merge($_GET,['page'=>$page-1]))?>">Previous</a><?php endif;?> <span>Page <?=$page?> of <?=ceil($total/$perPage)?></span> <?php if($offset+$perPage<$total):?><a class="button" href="?<?=http_build_query(array_merge($_GET,['page'=>$page+1]))?>">Next</a><?php endif;?></nav><?php endif;?><?php endif;?></section></div></main></div></body></html>
